'use strict';
// Immediate task feedback, with one short transition instead of repeated Check/Next gates.
const QuickPlay=(()=>{let manual=prInitialFlow==='manual',paused=false,pending=null,seen=null,lastEvaluation='',interaction=0,baseline=0,queued=false;try{manual=manual||localStorage.getItem('spotmatch-answer-pace')==='manual';}catch{}
 const ids=new WeakMap();let uid=0;const id=o=>{if(!ids.has(o))ids.set(o,++uid);return ids.get(o);};const q=sel=>app.querySelector(sel),hide=sel=>app.querySelectorAll(sel).forEach(el=>el.classList.add('quick-hide'));const nexts=['#next','#interactive-next','#learningNext','#adultNext','#senNext','#focusNext'];
 function cancel(){if(pending){clearTimeout(pending.timer);pending=null;}}
 function describe(){if(q('.calm-play')&&q('#calmFinish')&&calmState)return{engine:'calm',state:calmState,key:'calm:'+id(calmState)+':'+calmState.step};if(q('.pr-play')&&prState&&!prState.paused)return{engine:'playroom',state:prState,key:'pr:'+id(prState)};if(q('.sen-play')&&q('#senCheck,#senNext')&&senState?.task)return{engine:'sen',state:senState,key:'sen:'+id(senState)+':'+senState.round};if(q('.focus-play')&&q('#focusCheck,#focusNext')&&focusState?.task&&!focusState.paused)return{engine:'focus',state:focusState,key:'focus:'+id(focusState)+':'+focusState.round};if(q('[data-adult-choice],#adultAdd')&&adultState)return{engine:'adult',state:adultState,key:'adult:'+id(adultState)+':'+adultState.round};if(q('[data-learning-choice]')&&learningState)return{engine:'learning',state:learningState,key:'learning:'+id(learningState)+':'+learningState.round};if(q('#interactive-next')&&current)return{engine:'interactive',state:current,key:'interactive:'+id(current)+':'+round};if(q('[data-choice]')&&current)return{engine:'visual',state:current,key:'visual:'+id(current)+':'+round};return null;}
 function text(el,value){if(el.textContent!==value)el.textContent=value;}
 function status(text='Great!',success=true){const el=q('.feedback,.pr-message');if(!el)return;if(el.textContent!==text)el.textContent=text;el.classList.toggle('quick-success',success);}
 function schedule(t,signature,callback,delay=900,validate=()=>true){if(paused)return;if(pending?.key===t.key&&pending.signature===signature)return;cancel();pending={key:t.key,signature,timer:setTimeout(()=>{pending=null;const now=describe();if(!manual&&!paused&&now?.key===t.key&&validate())callback();},delay)};}
 function evaluate(t,fingerprint,callback){const signature=t.key+':'+fingerprint+':'+interaction;if(signature===lastEvaluation)return false;lastEvaluation=signature;callback();return true;}
 function pauseControl(){const controls=q('.game-controls,.sen-controls,.calm-controls,.pr-play-footer');if(!controls)return;let b=controls.querySelector('#quickPause');if(!b){b=document.createElement('button');b.id='quickPause';b.className='back quick-pause';b.onclick=()=>{paused=!paused;cancel();refresh();};controls.append(b);}const label=paused?'Resume automatic progress':'Pause automatic progress';if(b.textContent!==label)b.textContent=label;}
 function senFinishChoice(s,picture,label){s.done=true;s.records.push({round:s.round,observation:s.observation||'not-recorded',helpUsed:s.hint,retries:s.retries,kind:s.task.mode});senFinish();if(picture!==undefined){const box=document.createElement('div');box.id='quickChosenTopic';box.className='sen-choice-home has-choice';box.innerHTML=`<span class="sen-choice-heading">Your choice</span><div class="sen-chosen-picture" role="img" aria-label="Chosen: ${senEscape(label)}">${senPicture(picture)}</div><span class="sen-choice-caption">${senEscape(label)}</span>`;q('.game-wrap h1')?.after(box);}}
 function openFinish(s){const original=q('#senCheck')?.onclick;if(!original)return;original();const next=q('#senNext');if(next)next.click();}
 function settings(){const parent=q('.pr-parent-content');if(!parent||!q('[data-pr-parent="help"][aria-pressed="true"]')||q('#quickManual'))return;const label=document.createElement('label');label.className='comfort-control';label.innerHTML=`<input type="checkbox" id="quickManual" ${manual?'checked':''}><span><b>Step-by-step mode, if needed</b><small>Normally answers get immediate feedback and correct tasks move on automatically. Turn this on if your child needs separate checking and continuing.</small></span>`;parent.append(label);label.querySelector('input').onchange=e=>{manual=e.target.checked;cancel();try{localStorage.setItem('spotmatch-answer-pace',manual?'manual':'automatic');}catch{}refresh();};}
 function childCopy(){app.querySelectorAll('.play-invitation,.game-stage>p,.feedback').forEach(el=>{if(el.children.length)return;const text=el.textContent,next=text.replace(/,? then (?:tap the check button|check(?: it| the whole| your order| your choices)?)\.?/gi,'.').replace(/Check your order when every space is filled\./g,'Fill each space to make your order.').replace(/Check the two choices in order\./g,'Choose both pictures in order.').replace(/Choose the two items, then check\./g,'Choose the two items.');if(next!==text)el.textContent=next;});}
 function install(){queued=false;settings();if(manual){cancel();app.classList.remove('quick-mode');app.querySelectorAll('.quick-hide').forEach(e=>e.classList.remove('quick-hide'));q('#quickPause')?.remove();return;}app.classList.add('quick-mode');childCopy();const t=describe();if(!t){cancel();seen=null;return;}if(seen!==t.key){cancel();seen=t.key;lastEvaluation='';baseline=interaction;}const s=t.state;pauseControl();if(paused){cancel();for(const sel of nexts){const el=q(sel);if(el&&!el.hidden){el.classList.remove('quick-hide');if(el.textContent!=='Continue →')el.textContent='Continue →';}}}
 if(t.engine==='visual'||t.engine==='interactive'){hide('#next,#interactive-next,#check-work');if(t.engine==='interactive'&&!answered&&[22,23].includes(game)){const a=current.target,b=current.built;const match=game===22?a.color===b.color&&a.dots===b.dots:a.dir===b.dir;if(match){evaluate(t,'built:'+JSON.stringify(b),()=>checkWork());return;}}if(answered){status();if(paused){q('#next,#interactive-next')?.classList.remove('quick-hide');return;}schedule(t,'correct',()=>q(t.engine==='visual'?'#next':'#interactive-next')?.click());}return;}
 if(t.engine==='adult'){hide('#adultCheck,#adultNext');if(!s.answered&&s.mode==='order'&&s.selected.length===s.answer.length){const signature=JSON.stringify(s.selected),ok=s.answer.every((v,i)=>s.selected[i]===v);if(ok){evaluate(t,signature,()=>adultCheck());return;}if(interaction>baseline)evaluate(t,signature,()=>{s.missed=true;renderAdultTask('Let’s move a picture and try again.');});return;}if(!s.answered&&s.mode==='counter'&&s.count===s.answer[0]){evaluate(t,'count:'+s.count,()=>adultCheck());return;}if(s.answered){status();if(paused)q('#adultNext')?.classList.remove('quick-hide');else schedule(t,'correct',()=>q('#adultNext')?.click());}return;}
 if(t.engine==='learning'){hide('#learningCheck,#learningNext');if(!s.answered&&(isSequenceTask()||s.mode==='combine')&&s.selected.length===s.answer.length){const ok=s.mode==='combine'?s.answer.every(v=>s.selected.includes(v)):s.answer.every((v,i)=>s.selected[i]===v),signature=JSON.stringify(s.selected);if(ok){evaluate(t,signature,()=>learningCheck());return;}if(interaction>baseline)evaluate(t,signature,()=>{s.missed=true;renderLearningTask('Let’s move a picture and try again.');});return;}if(s.answered){status();if(paused)q('#learningNext')?.classList.remove('quick-hide');else schedule(t,'correct',()=>q('#learningNext')?.click());}return;}
 if(t.engine==='sen'){const mode=s.task.mode,g=supportPathways[s.key].games[s.index];hide('#senCheck,#senNext');if(mode==='book'){const next=q('#senPageNext');if(next&&s.page===s.task.pages.length-1&&!s.done){next.disabled=false;text(next,s.round+1===practiceRounds(3)?'Finish the story →':'Next little story →');next.onclick=()=>openFinish(s);}return;}if(mode==='compose'){const check=q('#senCheck');if(check&&!s.done){check.classList.remove('quick-hide');text(check,'Finish my story →');check.onclick=()=>senFinishChoice(s,undefined,'');}return;}
 if(mode==='explore'&&s.selection!==null&&!s.done){const choice=s.task.options[s.selection],label=g.kind==='theme'?['Trains','Animals','A picnic'][s.selection]:senDescription(choice.picture);status('Lovely choice!');if(paused){const b=q('#senCheck');if(b){b.classList.remove('quick-hide');text(b,'Continue →');b.onclick=()=>senFinishChoice(s,choice.picture,label);}}else schedule(t,'choice:'+s.selection,()=>senFinishChoice(s,choice.picture,label),1100,()=>s.selection!==null&&s.task.options[s.selection]===choice);return;}
 if(!s.done){let ready=false,ok=false;if(['choice','place'].includes(mode)&&s.selection!==null){ready=true;ok=s.task.answer.includes(s.task.options[s.selection]?.id);}else if(mode==='order'&&s.selected.length===s.task.answer.length){ready=true;ok=s.selected.every((v,i)=>v===s.task.answer[i]);}else if(mode==='counter'&&s.count===s.task.answer[0]){ready=true;ok=true;}else if(mode==='activate'&&s.reveal){const b=q('#senCheck');if(b){b.classList.remove('quick-hide');text(b,'Finish exploring →');b.onclick=()=>senFinishChoice(s,undefined,'');}return;}if(ready){const signature=JSON.stringify([s.selection,s.selected,s.count]);if(ok){evaluate(t,signature,()=>q('#senCheck')?.click());return;}evaluate(t,signature,()=>{s.retries++;s.response=mode==='order'?'Let’s move a picture and try again.':'Let’s try another picture.';senRender();});return;}}
 if(s.done){status();if(paused)q('#senNext')?.classList.remove('quick-hide');else schedule(t,'correct',()=>q('#senNext')?.click());}return;}
 if(t.engine==='focus'){hide('#focusCheck,#focusNext');const mode=s.task.mode;if(['open','plan'].includes(mode)){const check=q('#focusCheck');if(check&&!s.done){check.classList.remove('quick-hide');const practicalHelp=mode==='open'&&focusGames[s.index].theme==='help';text(check,practicalHelp?'Try with this help →':mode==='plan'?'Finish my plan →':'Continue →');if(!check.dataset.quickCombined){check.dataset.quickCombined='true';const initial=check.onclick;check.onclick=()=>{if(practicalHelp){worldStart(1,+s.selected[0]);return;}initial?.();q('#focusNext')?.click();};}}return;}if(!s.done){const ready=mode==='route'?s.selected.length===s.task.answer.length:mode==='order'||mode==='checklist'||mode==='collect'?s.selected.length===s.task.answer.length:s.selected.length>0;if(ready){const ok=['order','route'].includes(mode)?s.selected.every((v,i)=>v===s.task.answer[i]):s.selected.length===s.task.answer.length&&s.selected.every(v=>s.task.answer.includes(v)),signature=JSON.stringify(s.selected);if(ok){evaluate(t,signature,()=>q('#focusCheck')?.click());return;}evaluate(t,signature,()=>{s.message=mode==='order'?'Let’s move a picture and try again.':'Let’s try another picture.';focusRender();});return;}}if(s.done){status();if(paused)q('#focusNext')?.classList.remove('quick-hide');else schedule(t,'correct',()=>q('#focusNext')?.click());}return;}
 if(t.engine==='calm'){const mode=calmActivities[s.index].mode;if(['find','match','clue','rule'].includes(mode)){hide('#calmCheck,#calmTry');if(s.selected!==null&&!s.found){if(s.selected===calmModel(s).answer){evaluate(t,'choice:'+s.selected,()=>q('#calmCheck')?.click());return;}evaluate(t,'wrong:'+s.selected,()=>{s.message='Let’s try another picture.';calmRender();});}if(s.found){status();if(paused){const next=q('#calmTry');if(next){next.classList.remove('quick-hide');text(next,'Continue →');}}else schedule(t,'correct',()=>calmFinish(),900,()=>s.found);}else if(pending?.key===t.key)cancel();}else if(mode==='path'&&s.path===3){status();if(!paused)schedule(t,'path-done',()=>calmFinish(),900,()=>s.path===3);}return;}
 if(t.engine==='playroom'){let complete=false;if(s.id==='bridge'){if(s.built.every(Boolean)&&!s.crossed){evaluate(t,'bridge-ready',()=>q('#prCross')?.click());return;}complete=s.crossed;hide('#prCross');}if(s.id==='train'&&s.order.every((v,i)=>v===i)){hide('#prTrainGo');if(!s.complete){evaluate(t,'train-ready',()=>q('#prTrainGo')?.click());return;}complete=true;}if(s.id==='beads'&&!s.free)complete=s.beads.length===6&&s.beads.every((v,i)=>v===[0,1,0,1,0,1][i]);if(s.id==='garden')complete=!!s.harvested;if(s.id==='map')complete=s.path.at(-1)===3;if(s.id==='traffic')complete=s.position===2;if(s.id==='picnic')complete=!!s.meal?.ate&&!!s.meal?.drank;if(complete){status('Great! You did it.');if(!paused)schedule(t,'finished',()=>prFinish(),1400,()=>{if(s.id==='picnic')return !!s.meal?.ate&&!!s.meal?.drank;return true;});}else if(pending?.key===t.key)cancel();}
 }
 function refresh(){if(!queued){queued=true;queueMicrotask(install);}}
 document.addEventListener('click',e=>{if(e.target.closest('[data-choice],[data-home],[data-pair],[data-color],[data-dots],[data-turn],[data-changed],[data-learning-choice],[data-slot],[data-adult-choice],#adultAdd,#adultRemove,[data-sen-choice],#senAdd,#senRemove,[data-focus-choice],[data-compose],[data-calm-choice],[data-calm-home],[data-pr-plank],[data-pr-bead],[data-pr-carriage]'))interaction++;},{capture:true});document.addEventListener('pointerup',e=>{if(e.target.closest('.tp-source'))interaction++;},{capture:true});new MutationObserver(refresh).observe(app,{childList:true,subtree:true});refresh();return{refresh,pause(){paused=true;cancel();refresh();},resume(){paused=false;refresh();},get manual(){return manual;}};})();
